    <script>document.addEventListener('DOMContentLoaded',()=>{const input=document.querySelector('[data-catalog-filter]'),select=document.querySelector('[data-catalog-options]');if(input&&select){const options=[...select.querySelectorAll('option')];input.addEventListener('input',()=>{const query=input.value.trim().toLowerCase();options.forEach(option=>{if(!option.value)return;option.hidden=query!==''&&!option.textContent.toLowerCase().includes(query);});});}const dialog=document.querySelector('[data-catalog-item-dialog]'),launcher=document.querySelector('[data-open-catalog-item]'),type=document.querySelector('[data-new-item-type]');const toggleType=()=>document.querySelectorAll('[data-service-only]').forEach(el=>el.hidden=type?.value!=='service');launcher?.addEventListener('click',()=>{dialog.showModal();toggleType();});dialog?.querySelectorAll('[data-close-catalog-item]').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog?.addEventListener('close',()=>launcher?.focus());type?.addEventListener('change',toggleType);document.querySelectorAll('[data-scaled-type]').forEach(selector=>{const sync=()=>{const container=selector.closest('[data-scaled-value]')||selector.closest('form')?.querySelector('[data-scaled-value]');if(!container)return;const type=selector.value;const prefix=container.querySelector('[data-currency-prefix]'),suffix=container.querySelector('[data-percent-suffix]'),label=container.querySelector('[data-scaled-label]');if(prefix)prefix.hidden=type!=='fixed';if(suffix)suffix.hidden=type!=='percent';if(label)label.textContent=type==='fixed'?'(USD)':type==='percent'?'(%)':'';};selector.addEventListener('change',sync);sync();});if(dialog?.hasAttribute('data-reopen')){dialog.showModal();toggleType();dialog.querySelector(':invalid')?.focus();}else{document.querySelector('[data-first-error]')?.focus();}});</script>
